import CoreGraphics

/// Where text may be written on each design, as a fraction of the note's square frame, and where
/// a push-pin goes (nil = the design already has tape, rings or a bow). Generated by scripts/generate_notes.py.
extension NoteDesign {
    var textRect: CGRect {
        switch self {
        case .scallopChecklist: return CGRect(x: 0.27, y: 0.17, width: 0.57, height: 0.46)
        case .spiralBear: return CGRect(x: 0.25, y: 0.14, width: 0.62, height: 0.46)
        case .tapedBear: return CGRect(x: 0.20, y: 0.22, width: 0.64, height: 0.42)
        case .bowChecklist: return CGRect(x: 0.25, y: 0.30, width: 0.61, height: 0.58)
        case .ringBinder: return CGRect(x: 0.17, y: 0.30, width: 0.68, height: 0.58)
        case .tapePad: return CGRect(x: 0.14, y: 0.22, width: 0.70, height: 0.46)
        case .spiralTab: return CGRect(x: 0.30, y: 0.22, width: 0.58, height: 0.50)
        case .tornCupcake: return CGRect(x: 0.32, y: 0.20, width: 0.56, height: 0.52)
        }
    }

    var pinY: Double? {
        switch self {
        case .scallopChecklist: return 0.12
        case .spiralBear: return nil
        case .tapedBear: return nil
        case .bowChecklist: return nil
        case .ringBinder: return nil
        case .tapePad: return nil
        case .spiralTab: return nil
        case .tornCupcake: return nil
        }
    }
}
